    pid=m.group(1)
    # Get context around patient ID
    start=max(0,m.end()-500)
    end=min(len(c),m.end()+800)
    snippet=c[start:end]

    # Look for date pattern
    date_pat=re.compile(r'recorded on\s+(?:the\s+)?(\w+)\s+(?:of\s+)?([\d]{1,2})(?:st|nd|rd|th)?\s+(\w+),\s+(\d{4})', re.I)
    date_m=date_pat.search(snippet)
    if date_m:
        day_map={'january':1,'february':2,'march':3,'april':4,'may':5,'june':6,'july':7,'august':8,'september':9,'october':10,'november':11,'december':12}
        ord_days={'first':1,'second':2,'third':3,'fourth':4,'fifth':5,'sixth':6,'seventh':7,'eighth':8,'ninth':9,'tenth':10,'eleventh':11,'twelfth':12,'thirteenth':13,'fourteenth':14,'fifteenth':15,'sixteenth':16,'seventeenth':17,'eighteenth':18,'nineteenth':19,'twentieth':20,'twenty-first':21,'twenty-second':22,'twenty-third':23,'twenty-fourth':24,'twenty-fifth':25,'twenty-sixth':26,'twenty-seventh':27,'twenty-eighth':28,'twenty-ninth':29,'thirtieth':30,'thirty-first':31}
