        if date_m.group(2) in ord_days:
            day=ord_days[date_m.group(2)]
        else:
            day=int(date_m.group(2))
        year=int(date_m.group(4))
        if mon:
            lab_date=datetime(year,mon,day)
        else:
            lab_date=None
    else:
        lab_date=None

    # Extract final creatinine - take the last value found
    cr_vals=re.findall(r'creatinine[^.]*?([\d.]+)\s*mg/dL', snippet, re.I)
    if cr_vals:
        final_cr=float(cr_vals[-1])
        entries.append({'pid':pid, 'lab_date':lab_date, 'creatinine':final_cr})

print(f'Total entries: {len(entries)}')
for e in entries[:10]:
